import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"十二文","description":"","frontmatter":{"title":"十二文","date":"2026-11-17T00:00:00.000Z","seq":12,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/十二文.md","filePath":"blogs/声律启蒙·上卷/十二文.md"}'),r={name:"blogs/声律启蒙·上卷/十二文.md"};function p(_,e,l,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="十二文" tabindex="-1">十二文 <a class="header-anchor" href="#十二文" aria-label="Permalink to &quot;十二文&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">家对国，武对文，四辅对三军。九经对三史，菊馥对兰芬。歌北鄙，咏南薰，迩听对遥闻。召公周太保，李广汉将军。闻化蜀民皆草偃，争权晋土已瓜分。巫峡夜深，猿啸苦哀巴地月；衡峰秋早，雁飞高贴楚天云。</p><p class="poem-stanza">欹对正，见对闻，偃武对修文。羊车对鹤驾，朝旭对晚曛。花有艳，竹成文，马燧对羊欣。山中梁宰相，树下汉将军。施帐解围嘉道韫，当垆沽酒叹文君。好景有期，北岭几枝梅似雪；丰年先兆，西郊千顷稼如云。</p><p class="poem-stanza">尧对舜，夏对殷，蔡惠对刘蕡。山明对水秀，五典对三坟。唐李杜，晋机云，事父对忠君。雨晴鸠唤妇，霜冷雁呼群。酒量洪深周仆射，诗才俊逸鲍参军。鸟翼长随，凤兮洵众禽长；狐威不假，虎也真百兽尊。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
